{
  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    # sort segments by importance descending, then by name for stable tie-break
    segs = sorted(segments, key=lambda s: (-s['importance'], s['name']))
    # initial allocation at minimum
    alloc = {s['name']: s['minimum'] for s in segs}
    remaining = budget - sum(s['minimum'] for s in segs)
    if remaining < 0:
        # infeasible; return minimum allocations (or raise?)
        return alloc
    for s in segs:
        if remaining <= 0:
            break
        cap = s['capacity']
        cur = alloc[s['name']]
        can_add = min(cap - cur, remaining)
        if can_add > 0:
            alloc[s['name']] += can_add
            remaining -= can_add
    return alloc"
